const native=typeof Android!=='undefined';const APP_VERSION=(()=>{try{return native?Android.appVersion():'1.3.0';}catch(e){return '1.3.0';}})();let s,loadError='',page='home',month=L.today().slice(0,7),book='all',recordType='all',recordRange='month',query='',filters={category:'all',account:'all',reimburse:'all',from:'',to:''},statsType='expense',selectedDate='',shown=80,draft=null,importData=null,importResult=null,pendingKind='',toastTimer,modalName='';
try{const raw=native?Android.readState():localStorage.getItem('qinghe.state');s=raw?L.validate(JSON.parse(raw)):L.initial();}catch(e){s=L.initial();loadError='本地数据未能读取：'+e.message;}
if(s.accounts.length>1&&s.accounts[0].id==='cash'&&s.accounts.some(a=>a.id==='wechat')){const cashAcc=s.accounts.find(a=>a.id==='cash');s.accounts=[...s.accounts.filter(a=>a.id!=='cash'),cashAcc];}
