function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function persist(next,recovery=false){if(loadError&&!recovery)throw Error('账本尚未恢复，不能覆盖原文件');const raw=L.stateJSON(next);if(native){const r=recovery?Android.saveRecoveredState(raw):Android.saveState(raw);if(r!=='ok')throw Error(r||'保存失败');}else localStorage.setItem('qinghe.state',raw);}
function commit(fn,message='',rerender=true){try{const next=L.clone(s);fn(next);persist(next);s=next;if(rerender)render();if(message)toast(message);return true;}catch(e){toast('未保存：'+e.message);return false;}}
let modalTimer,modalEpoch=0,lastTrigger=null,hiddenTrigger=null,searchTimer=null;function hideTrigger(t){if(hiddenTrigger&&hiddenTrigger!==t&&hiddenTrigger.isConnected)hiddenTrigger.style.opacity='';hiddenTrigger=t;t.style.opacity='0';}function showTrigger(){if(hiddenTrigger&&hiddenTrigger.isConnected){hiddenTrigger.style.transition='opacity .12s ease';hiddenTrigger.style.opacity='';}hiddenTrigger=null;}
const reducedMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function modal(title,body,{wide=false,name=''}={}){const el=$('#modal'),wasOpen=!el.hidden&&!el.classList.contains('closing'),sameForm=wasOpen&&name==='record'&&modalName==='record',scroll=sameForm?el.querySelector('.sheet').scrollTop:0;clearTimeout(modalTimer);modalEpoch++;el.classList.remove('closing');el.inert=false;el.innerHTML=`<section class="sheet ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-head row between"><h2>${esc(title)}</h2>${act('close',icon('close'),'icon-btn','aria-label="关闭"')}</div>${body}</section>`;el.hidden=false;document.body.classList.add('scroll-lock');const sheet=el.querySelector('.sheet');sheet.scrollTop=scroll;modalName=name;void sheet.offsetHeight;enhanceSelects();if(!sameForm){const t=lastTrigger;if(t&&t.isConnected){const br=t.getBoundingClientRect(),sr=sheet.getBoundingClientRect(),ox=br.left+br.width/2-sr.left,oy=br.top+br.height/2-sr.top;sheet.style.transformOrigin=Math.max(0,Math.min(sr.width,ox))+'px '+Math.max(0,Math.min(sr.height,oy))+'px';sheet.style.setProperty('--sx',.40);sheet.style.setProperty('--sy',.40);hideTrigger(t);}else{sheet.style.transformOrigin='';sheet.style.setProperty('--sx',.40);sheet.style.setProperty('--sy',.40);}}const epoch=modalEpoch;const start=()=>{if(epoch!==modalEpoch)return;if(!wasOpen)el.classList.add('overlay-enter');if(!sameForm)sheet.classList.add(wasOpen?'sheet-refresh':'sheet-grow');};if(reducedMotion())start();else requestAnimationFrame(start);}
function close(){const el=$('#modal');if(el.hidden||el.classList.contains('closing'))return;const epoch=++modalEpoch;modalName='';closePicker();el.inert=true;el.classList.remove('overlay-enter');el.classList.add('closing');const finish=()=>{if(epoch!==modalEpoch)return;el.hidden=true;el.classList.remove('closing');el.inert=false;showTrigger();requestAnimationFrame(()=>{if(epoch!==modalEpoch)return;el.innerHTML='';document.body.classList.remove('scroll-lock');});};if(reducedMotion())finish();else modalTimer=setTimeout(finish,310);}
function empty(title,desc,action='add',label='记第一笔',ic='leaf'){return `<div class="empty"><div class="empty-illustration">${icon(ic)}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action?act(action,label,'button secondary'):''}</div>`;}
function monthNav(){return `<div class="month-nav">${act('month-prev','‹','','aria-label="上个月"')}<input type="month" id="month" aria-label="查看月份" value="${month}" min="1900-01" max="2200-12">${act('month-next','›','','aria-label="下个月"')}<span class="grow"></span>${act('month-today','回到本月','text-btn')}</div>`;}
function top(title,sub){return `<header class="page-top row between"><div><div class="eyebrow">${esc(sub)}</div><h1>${esc(title)}</h1></div><div class="row gap8"><select id="bookScope" class="book-switch" aria-label="选择账本">${options(s.books,book,'全部账本')}</select>${act('nav-more',icon('settings'),'icon-btn','aria-label="设置与更多"')}</div></header>`;}
function tx(t){const c=find('categories',t.category),caption=t.type==='transfer'?name('accounts',t.account)+' → '+name('accounts',t.to):c?.name;return `<button class="transaction" data-action="edit" data-id="${esc(t.id)}"><span class="category-icon">${t.type==='transfer'?icon('transfer'):esc(c?.icon||'◌')}</span><span class="grow"><span class="tx-title" style="display:block">${esc(caption)}${t.image?' · 图片':''}</span><span class="tx-sub" style="display:block">${esc([t.note||name('accounts',t.account),t.member,t.reimburse==='pending'?'待报销':t.reimburse==='done'?'已报销':''].filter(Boolean).join(' · '))}</span></span><span class="tx-amount ${t.type}">${t.type==='expense'?'−':t.type==='income'?'+':''}${money(t.amount)}</span></button>`;}
function txList(list,limit=shown){if(!list.length)return empty('这里还没有记录','每一笔小记录，都是生活的足迹。');const daySum=new Map();for(const t of list){const d=daySum.get(t.date)||{income:0,expense:0};if(t.type==='income')d.income+=t.amount;else if(t.type==='expense')d.expense+=t.amount;daySum.set(t.date,d);}let html='',date='';for(const t of list.slice(0,limit)){if(t.date!==date){if(date)html+='</div>';date=t.date;const sum=daySum.get(t.date)||{income:0,expense:0};html+=`<div class="day-label row between"><span>${esc(date)}</span><span>支 ${money(sum.expense)} · 收 ${money(sum.income)}</span></div><div class="card flat">`;}html+=tx(t);}if(date)html+='</div>';if(list.length>limit)html+=`<div class="load-more">${act('more-records',`继续加载 · 共 ${list.length} 笔`,'button secondary')}</div>`;return html;}
function budgetCard(){const total=L.budget(s,month,book),spent=L.summary(rows()).expense,ratio=total?Math.min(100,spent/total*100):0;return `<div class="card"><div class="row between"><div class="row gap8">${icon('target')}<h3>本月预算</h3></div>${act('budgets',total?'管理预算':'设置预算','text-btn')}</div>${total?`<div class="row between" style="margin-top:16px"><span class="small muted">${spent>total?'已超出':'还可以花'}</span><strong class="${spent>total?'expense':''}">¥ ${money(Math.abs(total-spent))}</strong></div><div class="budget-track"><div class="budget-fill ${spent>total?'over':''}" style="width:${ratio}%"></div></div><div class="row between tiny muted"><span>已用 ${s.settings.hideAmounts?'—':Math.round(spent/total*100)+'%'}</span><span>总预算 ¥ ${money(total)}</span></div>`:`<p class="small muted" style="margin-top:13px">给开销定个小目标，让每一笔都心中有数。</p>`}</div>`;}
function home(){const list=rows(),sum=L.summary(list),budget=L.budget(s,month,book);return `<div class="home-page">`+top('青禾账本','')+monthNav()+`<section class="card home-summary" aria-label="本月收支"><div><div class="summary-label">结余 ${act('hide',icon('eye'),'summary-eye','aria-label="显示或隐藏金额"')}</div><strong class="mono summary-net">${money(sum.net)}</strong></div><div><span class="summary-label">收入</span><strong class="mono income">${money(sum.income)}</strong></div><div><span class="summary-label">支出</span><strong class="mono expense">${money(sum.expense)}</strong></div></section><div class="grid3 quick-actions">${act('add',icon('minus')+'记支出','','data-type="expense"')}${act('add',icon('plus')+'记收入','','data-type="income"')}${act('add',icon('transfer')+'转账','','data-type="transfer"')}</div>${budget?`<div class="home-budget row between"><span>本月预算 · ${sum.expense>budget?'已超出':'剩余'} ${money(Math.abs(budget-sum.expense))}</span>${act('budgets','调整','text-btn')}</div>`:''}<section class="home-records section"><div class="section-head row between"><div class="row gap8"><h2>本月明细</h2><span class="count-badge">${list.length} 笔</span></div>${act('nav-records',icon('search','mini-icon')+' 搜索 / 筛选','text-btn')}</div>${txList(list)}</section><div class="home-tools row wrap">${act('budgets','月度预算','chip')}${act('nav-calendar','收支日历','chip')}</div><div class="footer-note">${icon('shield','mini-icon')} 仅存本机 · 无需账号 · 无会员限制</div></div>`;}
function records(){const list=recordRows(),sum=L.summary(list);return top('收支明细','每一笔，都有迹可循')+monthNav()+`<div class="chip-row" style="margin-bottom:14px">${act('record-range','本月','chip '+(recordRange==='month'?'active':''),'data-id="month"')}${act('record-range','全部日期','chip '+(recordRange==='all'?'active':''),'data-id="all"')}</div>`+`<div class="toolbar"><div class="search-wrap">${icon('search')}<input id="search" placeholder="搜索备注、分类、金额…" value="${esc(query)}" aria-label="搜索账目"></div>${act('filters',icon('settings'),'icon-btn','aria-label="筛选账目"')}</div><div class="row between wrap"><div class="chip-row">${[['all','全部'],['expense','支出'],['income','收入'],['transfer','转账']].map(([id,n])=>act('record-type',n,'chip '+(recordType===id?'active':''),`data-id="${id}"`)).join('')}</div>${act('export-current',icon('download','mini-icon')+' 导出','text-btn')}</div><div class="small muted" style="margin-top:14px">共 ${list.length} 笔 · 收入 ${money(sum.income)} · 支出 ${money(sum.expense)}</div>${txList(list)}`;}
