function donut(groups,total){let off=0;const circles=groups.map((g,i)=>{const len=total?g.total/total*251.327:0,h=`<circle cx="55" cy="55" r="40" fill="none" stroke="${colors[i%colors.length]}" stroke-width="12" stroke-dasharray="${len} ${251.327-len}" stroke-dashoffset="${-off}" transform="rotate(-90 55 55)"/>`;off+=len;return h;}).join('');return `<svg class="donut" viewBox="0 0 110 110" role="img" aria-label="分类占比图"><circle cx="55" cy="55" r="40" fill="none" stroke="var(--line)" stroke-width="12"/>${circles}<text x="55" y="52" text-anchor="middle" fill="var(--muted)" font-size="8">${statsType==='expense'?'支出分类':'收入分类'}</text><text x="55" y="67" text-anchor="middle" fill="var(--ink)" font-size="14" font-weight="600">${groups.length} 类</text></svg>`;}
